struct boss_god_king_skovaldAI : public BossAI
    {
        boss_god_king_skovaldAI(Creature* creature) : BossAI(creature, DATA_SKOVALD) 
        {
            if (me->IsAlive())
            {
                me->SetVisible(false);
                intro = true;
                kingDiedCount = 0;
                AddDelayedEvent(500, [=] () -> void { SummonOdynKings(); });
            }
        }

        bool intro;
        bool aegisEvent;
        uint8 kingDiedCount;
        uint8 power, powerCounter;
        uint16 powerTimer;
        std::set<ObjectGuid> KingGUIDs;

        void Reset() override
        {
            _Reset();

            DoCast(me, SPELL_ZERO_REGEN, true);
            me->SetFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_NON_ATTACKABLE);
            me->SetReactState(REACT_PASSIVE);
            me->SetPower(POWER_ENERGY, 80);
            me->RemoveAurasDueToSpell(SPELL_RAGNAROK_MOD);
            aegisEvent = false;
            powerTimer = 1000;

            if (!intro)
            {
                AddDelayedEvent(10000, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)] () -> void
                {
                    if (aiLifetimeGuard.expired()) return;
                    me->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_NON_ATTACKABLE);
                    me->SetReactState(REACT_DEFENSIVE);
                });

                if (auto odyn = instance->instance->GetCreature(instance->GetGuidData(DATA_ODYN)))
                    odyn->CastSpell(odyn, SPELL_AEGIS_SPAWN, true);
            }
        }

        void EnterCombat(Unit* /*who*/) override
        {
            Talk(SAY_AGGRO); //Give up the aegis or die!
            _EnterCombat();
            events.RescheduleEvent(EVENT_FELBLAZE_RUSH, 7000);
            events.RescheduleEvent(EVENT_SAVAGE_BLADE, 24000);
            DoCast(me, 202366, true); //Remove Odyn's Blessing - Speed buff
        }

        void JustDied(Unit* /*killer*/) override
        {
            Talk(SAY_DEATH);
            _JustDied();
        }

        void SummonOdynKings()
        {
            if (instance->GetData(DATA_SKOVALD_EVENT) == DONE)
                KingsEventComplete();
            else
            {
                for (uint8 i = 0; i < 4; i++)
                    me->SummonCreature(OdynKings[i], kingsPos[i]);
            }
        }

        void KingsEventComplete()
        {
            KingGUIDs.clear();
            me->SetVisible(true);
            me->SetPower(POWER_ENERGY, 80);
            me->GetMotionMaster()->MovePoint(1, 2411.03f, 528.72f, 748.99f);
            DoCast(me, SPELL_CONVERSATION, true);

            if (auto odyn = instance->instance->GetCreature(instance->GetGuidData(DATA_ODYN)))
            {
                odyn->AI()->Talk(1); // Победителям - достойная награда
                odyn->CastSpell(odyn, SPELL_AEGIS_SPAWN, true);
            }
            if (instance->GetData(DATA_SKOVALD_EVENT) != DONE)
                instance->SetData(DATA_SKOVALD_EVENT, DONE);
        }

        void DoAction(int32 const action, Creature* caller) override
        {
            if (!caller)
                return;

            if (action == ACTION_1)
            {
                KingGUIDs.erase(caller->GetGUID());
                caller->setFaction(16);
                caller->AI()->DoZoneInCombat(caller, 100.0f);

                if (KingGUIDs.size() == 1)
                {
                    for (auto guid : KingGUIDs)
                    {
                        if (Creature* King = Creature::GetCreature(*me, guid))
                        {
                            King->setFaction(16);
                            King->AI()->DoZoneInCombat(King, 100.0f);
                        }
                    }
                }
            }
            else if (action == ACTION_2)
            {
                KingGUIDs.insert(caller->GetGUID());
            }
        }

        void SummonedCreatureDies(Creature* summon, Unit* /*killer*/) override
        {
            if (!intro)
                return;

            switch (summon->GetEntry())
            {
                case NPC_KING_HALDOR:
                case NPC_KING_BJORN:
                case NPC_KING_RANULF:
                case NPC_KING_TOR:
                    kingDiedCount++;
                    break;
            }

            if (kingDiedCount == 4)
                KingsEventComplete();
        }

        void MovementInform(uint32 type, uint32 id) override
        {
            if (type != POINT_MOTION_TYPE)
                return;

            if (id == 1)
            {
                me->SetHomePosition(me->GetPositionX(), me->GetPositionY(), me->GetPositionZ(), me->GetOrientation());
                events.RescheduleEvent(EVENT_INTRO_COMPLETE, 24000);
            }
            else if (id == 2)
            {
                events.DelayEvents(3000);
                DoCast(SPELL_CLAIM_THE_AEGIS);
            }
        }

        void SpellHit(Unit* caster, const SpellInfo* spell) override
        {
            if (spell->Id == 193988)
            {
                if (auto target = SelectTarget(SELECT_TARGET_TOPAGGRO))
                    me->SetFacingToObject(target);
                DoCast(me, SPELL_INFERNAL_FLAMES_AURA, true);
                aegisEvent = false;
                Talk(SAY_EGIDA);
                me->SetReactState(REACT_AGGRESSIVE, 10000);
            }
        }

        void SpellHitTarget(Unit* target, const SpellInfo* spell) override
        {
            switch (spell->Id)
            {
                case SPELL_SAVAGE_BLADE:
                    if (me->GetGUID() != target->GetGUID() && !target->IsActiveMitigation())
                        me->CastSpell(target, 193686, true);
                    break;
                case SPELL_INFERNAL_FLAMES_FIND_N:
                    if (!me->isInBack(target, float(M_PI * 0.8f)))
                        DoCast(target, SPELL_INFERNAL_FLAMES_TRIG_AT, true);
                    break;
                case SPELL_INFERNAL_FLAMES_FIND_H:
                    DoCast(target, SPELL_INFERNAL_FLAMES_TRIG_SUM, true);
                    break;
            }
        }

        void OnApplyOrRemoveAura(uint32 spellId, AuraRemoveMode mode, bool apply) override
        {
            if (apply || !me->isInCombat() || mode != AURA_REMOVE_BY_EXPIRE)
                return;

            if (spellId == SPELL_RAGNAROK)
                me->RemoveAurasDueToSpell(SPELL_RAGNAROK_MOD);
        }

        void DoAction(int32 const action) override
        {
            events.RescheduleEvent(EVENT_PICK_AEGIS, 100);
        }

        void UpdateAI(uint32 diff) override
        {
            if (!UpdateVictim() && !intro)
                return;

            events.Update(diff);

            if (me->isInCombat())
            {
                if (powerTimer <= diff)
                {
                    powerTimer = 1000;
                    power = me->GetPower(POWER_ENERGY);

                    if (power < 100)
                    {
                        if (powerCounter < 2)
                        {
                            powerCounter++;
                            me->SetPower(POWER_ENERGY, power + 2);
                        }
                        else
                        {
                            powerCounter = 0;
                            me->SetPower(POWER_ENERGY, power + 1);
                        }
                    }
                    else if (!me->HasUnitState(UNIT_STATE_CASTING))
                    {
                        powerTimer = 4000;
                        events.RescheduleEvent(EVENT_RAGNAROK, 500);
                    }
                }
                else powerTimer -=diff;
            }

            if (me->HasUnitState(UNIT_STATE_CASTING) || aegisEvent)
                return;

            if (!intro)
                if (CheckHomeDistToEvade(diff, 61.0f, 2441.64f, 528.51f, 748.99f))
                    return;

            if (uint32 eventId = events.ExecuteEvent())
            {
                switch (eventId)
                {
                    case EVENT_INTRO_COMPLETE:
                        intro = false;
                        me->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_NON_ATTACKABLE);
                        me->SetReactState(REACT_DEFENSIVE);
                        break;
                    case EVENT_FELBLAZE_RUSH:
                        DoCast(SPELL_FELBLAZE_RUSH);
                        events.RescheduleEvent(EVENT_FELBLAZE_RUSH, urand(10, 26) * IN_MILLISECONDS);
                        break;
                    case EVENT_RAGNAROK:
                        DoCast(SPELL_RAGNAROK);
                        Talk(SAY_RAGNAROK);
                        Talk(SAY_RAGNAROK_EMOTE);
                        break;
                    case EVENT_PICK_AEGIS:
                        aegisEvent = true;
                        me->StopAttack();
                        if (auto aegis = me->FindNearestCreature(NPC_AEGIS_OF_AGGRAMAR, 60.0f))
                            me->GetMotionMaster()->MovePoint(2, aegis->GetPositionX(), aegis->GetPositionY(), aegis->GetPositionZ());
                        else
                        {
                            aegisEvent = false;
                            me->SetReactState(REACT_AGGRESSIVE);
                        }
                        break;
                    case EVENT_SAVAGE_BLADE:
                        DoCastTopAggro(SPELL_SAVAGE_BLADE);
                        events.RescheduleEvent(EVENT_SAVAGE_BLADE, 24000);
                        break;
                }
            }
            DoMeleeAttackIfReady();
        }
    private:
        // Unit-owned queues may outlive this AI object.
        std::shared_ptr<uint8> _delayedAILifetimeGuard = std::make_shared<uint8>(0);
    }

