                poolGUID.push_back(pool->GetGUID());
                pool->AI()->SetData(DATA_POOL_IDX, idx++);
            }

        if (introEvent)
        {
            SummonGrasping(true);
            SummonDestructor(true);
        }
    }

    void EnterCombat(Unit* /*who*/) override
    {
        Talk(SAY_AGGRO);
        _EnterCombat();
        events.RescheduleEvent(EVENT_TAINT_SEA, 0);
